func (q *Queries) ListRealtimeOutboxAfter(ctx context.Context, arg ListRealtimeOutboxAfterParams) ([]ListRealtimeOutboxAfterRow, error) {
	rows, err := q.db.Query(ctx, listRealtimeOutboxAfter,
		arg.TournamentID,
		arg.AfterSequence,
		arg.Role,
		arg.PrincipalID,
		arg.BatchSize,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListRealtimeOutboxAfterRow{}
	for rows.Next() {
		var i ListRealtimeOutboxAfterRow
		if err := rows.Scan(
			&i.ID,
			&i.IdempotencyKey,
			&i.TournamentID,
			&i.ProjectionRevisionID,
			&i.Sequence,
			&i.ProjectionRevision,
			&i.ProjectionOrdinal,
			&i.Terminal,
			&i.Audience,
			&i.PrincipalID,
			&i.Topic,
			&i.Payload,
			&i.CreatedAt,
			&i.AttemptCount,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

