const retryRealtimeDelivery = `-- name: RetryRealtimeDelivery :one
WITH locked_subscriber AS MATERIALIZED (
    SELECT subscriber.id
    FROM realtime_subscribers AS subscriber
    WHERE subscriber.id = $6
        AND subscriber.instance_id = $7
        AND subscriber.connection_id = $8
        AND subscriber.connection_generation = $9
        AND subscriber.closed_at IS NULL
    FOR UPDATE OF subscriber
)
UPDATE realtime_delivery_receipts AS receipt
SET available_at = $1,
    claimed_by = NULL,
    claim_token = NULL,
    claimed_until = NULL,
    last_error = $2
FROM locked_subscriber AS subscriber
WHERE receipt.subscriber_id = subscriber.id
    AND receipt.event_id = $3
    AND receipt.terminal_at IS NULL
    AND receipt.claimed_by = $4
    AND receipt.claim_token = $5
RETURNING receipt.subscriber_id
`

type RetryRealtimeDeliveryParams struct {
	AvailableAt          pgtype.Timestamptz
	Reason               *string
	EventID              uuid.UUID
	WorkerID             uuid.NullUUID
	ClaimToken           uuid.NullUUID
	SubscriberID         uuid.UUID
	InstanceID           uuid.UUID
	ConnectionID         uuid.UUID
	ConnectionGeneration int64
}

func (q *Queries) RetryRealtimeDelivery(ctx context.Context, arg RetryRealtimeDeliveryParams) (uuid.UUID, error) {
	row := q.db.QueryRow(ctx, retryRealtimeDelivery,
		arg.AvailableAt,
		arg.Reason,
		arg.EventID,
		arg.WorkerID,
		arg.ClaimToken,
		arg.SubscriberID,
		arg.InstanceID,
		arg.ConnectionID,
		arg.ConnectionGeneration,
	)
	var subscriber_id uuid.UUID
	err := row.Scan(&subscriber_id)
	return subscriber_id, err
}

